--   0x14: lh   x2, 0(x20)     # 0x00001234
--   0x18: lh   x3, 2(x20)     # 0xFFFFABCD
--   0x1C: lhu  x4, 0(x20)     # 0x00001234
--   0x20: lhu  x5, 2(x20)     # 0x0000ABCD
--   0x24: lb   x6, 0(x20)     # 0x00000034
--   0x28: lb   x7, 2(x20)     # 0xFFFFFFCD
--   0x2C: lbu  x8, 0(x20)     # 0x34
--   0x30: lbu  x9, 2(x20)     # 0xCD
--   0x34: lb   x11, 1(x20)    # 0x12
--   0x38: lb   x12, 3(x20)    # 0xFFFFFFAB
--   0x3C: jal x0, halt        # end of program
