library ieee;
use ieee.std_logic_1164.all;
use ieee.numeric_std.all;

library work;
use work.tb_pkg.all;

entity tb_all_loads is
end entity tb_all_loads;

architecture sim of tb_all_loads is
    signal clk        : std_logic := '0';
    signal rst        : std_logic := '1';
    signal dbg_pc     : std_logic_vector(31 downto 0);
    signal dbg_instr  : std_logic_vector(31 downto 0);
    signal dbg_reg_we : std_logic;
    signal dbg_reg_wa : std_logic_vector(4 downto 0);
    signal dbg_reg_wd : std_logic_vector(31 downto 0);

    -- Shadow register file built from the write-back port, plus the cycle
    -- (counted from reset release) of each register's latest write.
    signal regs       : reg_array_t := (others => (others => '0'));
    signal wcycle     : int_array_t := (others => -1);
    signal cycle      : integer := 0;
    signal clear_regs : std_logic := '0';

    constant PROG : prog_t := (
         0 => x"ABCD10B7",
         1 => x"23408093",
         2 => x"10000A13",
         3 => x"001A2023",
         4 => x"000A2503",
         5 => x"000A1103",
         6 => x"002A1183",
         7 => x"000A5203",
         8 => x"002A5283",
         9 => x"000A0303",
        10 => x"002A0383",
        11 => x"000A4403",
        12 => x"002A4483",
        13 => x"001A0583",
        14 => x"003A0603",
        15 => x"0000006F"
    );
    constant HEX_FILE : string := write_hex("/tmp/tb_all_loads.hex", PROG);

begin
    clk <= not clk after CLK_PERIOD / 2;

    dut: entity work.pipeline_top
        generic map (MEM_DEPTH => 256, IMEM_INIT => HEX_FILE)
        port map (clk => clk, rst => rst,
                  dbg_pc => dbg_pc, dbg_instr => dbg_instr,
                  dbg_reg_we => dbg_reg_we,
                  dbg_reg_wa => dbg_reg_wa,
                  dbg_reg_wd => dbg_reg_wd);

    process(clk)
    begin
        if rising_edge(clk) then
            if rst = '1' then
                cycle <= 0;
            else
                cycle <= cycle + 1;
            end if;
            if clear_regs = '1' then
                regs   <= (others => (others => '0'));
                wcycle <= (others => -1);
            elsif dbg_reg_we = '1' and unsigned(dbg_reg_wa) /= 0 then
                regs(to_integer(unsigned(dbg_reg_wa)))   <= dbg_reg_wd;
                wcycle(to_integer(unsigned(dbg_reg_wa))) <= cycle;
            end if;
        end if;
    end process;

    process
        variable errors : natural := 0;
    begin
        rst <= '1';
        wait for 3 * CLK_PERIOD;
        rst <= '0';
        wait for 80 * CLK_PERIOD;

        check_reg(regs, 2, x"00001234", "x2", errors);
        check_reg(regs, 3, x"FFFFABCD", "x3", errors);
        check_reg(regs, 4, x"00001234", "x4", errors);
        check_reg(regs, 5, x"0000ABCD", "x5", errors);
        check_reg(regs, 6, x"00000034", "x6", errors);
        check_reg(regs, 7, x"FFFFFFCD", "x7", errors);
        check_reg(regs, 8, x"00000034", "x8", errors);
        check_reg(regs, 9, x"000000CD", "x9", errors);
        check_reg(regs, 10, x"ABCD1234", "x10", errors);
        check_reg(regs, 11, x"00000012", "x11", errors);
        check_reg(regs, 12, x"FFFFFFAB", "x12", errors);

        finish_test("tb_all_loads", errors);
        wait;
    end process;
end architecture sim;
